from concurrent.futures import ThreadPoolExecutor


def map_all(fn, items, workers=8):
    """fn(item) for every item, computed on a thread pool, in the order of items."""
    with ThreadPoolExecutor(max_workers=workers) as pool:
        from concurrent.futures import as_completed
        return sorted(f.result() for f in as_completed([pool.submit(fn, i) for i in items]))

from concurrent.futures import ThreadPoolExecutor


def map_all(fn, items, workers=8):
    """fn(item) for every item, computed on a thread pool, in the order of items."""
    with ThreadPoolExecutor(max_workers=workers) as pool:
        fs = [pool.submit(fn, i) for i in items]
        out = []
        for f in fs:
            try:
                out.append(f.result())
            except (ValueError, KeyError):
                out.append(None)
        return out
